package sn.casamance.reservation;
import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import org.springframework.beans.factory.annotation.Value; import java.time.LocalDate; import java.util.*;
@Component class ReservationCatalogClient { private final RestClient client; ReservationCatalogClient(RestClient.Builder b,@Value("${reservation.service-url:http://localhost:8082}") String url){client=b.baseUrl(url).build();} List<VisitSnapshot> visits(){VisitSnapshot[] v=client.get().uri("/api/visits").retrieve().body(VisitSnapshot[].class);return v==null?List.of():List.of(v);} boolean available(Long id,LocalDate date,int travelers){Boolean ok=client.get().uri(u->u.path("/api/visits/{id}/availability").queryParam("date",date).queryParam("travelers",travelers).build(id)).retrieve().body(Boolean.class);return Boolean.TRUE.equals(ok);} }
